internal fun parseDnsAnswer(text: String, hostname: String, type: Int, now: Long, ageSeconds: Long = 0): DnsAnswer {
  val json = JSONObject(text)
  if (json.optInt("Status", -1) != 0 || json.optBoolean("TC", false)) throw IOException("DNS answer failure")
  val questions = json.optJSONArray("Question") ?: throw IOException("DNS question missing")
  if (questions.length() != 1) throw IOException("DNS question mismatch")
  fun name(value: String) = value.lowercase(Locale.ROOT).removeSuffix(".")
  val question = questions.getJSONObject(0)
  if (name(question.optString("name")) != hostname || question.optInt("type", -1) != type) throw IOException("DNS question mismatch")
  val records = json.optJSONArray("Answer") ?: return DnsAnswer(emptyList(), now)
  if (records.length() > 64) throw IOException("Too many DNS answers")
  var minimumTtl = MAX_CACHE_SECONDS
  val names = linkedSetOf(hostname)
  repeat(8) {
    for (i in 0 until records.length()) {
      val record = records.getJSONObject(i)
      if (record.optInt("type") == 5 && name(record.optString("name")) in names) {
        val alias = name(record.optString("data"))
        if (!Regex("[a-z0-9](?:[a-z0-9.-]{0,251}[a-z0-9])?").matches(alias)) throw IOException("DNS alias invalid")
        minimumTtl = minOf(minimumTtl, dnsTtl(record))
        names.add(alias)
      }
    }
  }
  val addresses = mutableListOf<InetAddress>()
  for (i in 0 until records.length()) {
    val record = records.getJSONObject(i)
    if (record.optInt("type") != type || name(record.optString("name")) !in names) continue
    val address = numericAddress(record.getString("data"))
    if ((type == 1 && address !is Inet4Address) || (type == 28 && address !is Inet6Address) || !publicAddress(address)) throw IOException("DNS address is not public")
    minimumTtl = minOf(minimumTtl, dnsTtl(record))
    addresses.add(address)
  }
  return DnsAnswer(addresses.distinct().take(16), now + TimeUnit.SECONDS.toNanos(maxOf(0, minimumTtl - ageSeconds)))
}

private fun dnsTtl(record: JSONObject): Long {
  val ttl = record.opt("TTL") as? Number ?: throw IOException("DNS TTL missing")
  val value = ttl.toLong()
  if (value < 0 || value > Int.MAX_VALUE || ttl.toDouble() != value.toDouble()) throw IOException("DNS TTL invalid")
  return value
}

/** Parses literal bytes only: resolver answers can never cause another system DNS lookup. */
internal fun numericAddress(value: String): InetAddress {
  if (!value.contains(':')) {
    val parts = value.split('.')
    if (parts.size != 4 || parts.any { !Regex("[0-9]{1,3}").matches(it) || it.toInt() !in 0..255 }) throw IOException("Invalid IPv4 address")
    return InetAddress.getByAddress(parts.map { it.toInt().toByte() }.toByteArray())
  }
  if (!Regex("[0-9a-fA-F:]+").matches(value) || value.split("::").size > 2) throw IOException("Invalid IPv6 address")
  val halves = value.split("::")
  fun groups(part: String) = if (part.isEmpty()) emptyList() else part.split(':')
  val left = groups(halves[0])
  val right = if (halves.size == 2) groups(halves[1]) else emptyList()
  val missing = 8 - left.size - right.size
  if ((halves.size == 1 && missing != 0) || (halves.size == 2 && missing < 1)) throw IOException("Invalid IPv6 length")
  val expanded = left + List(missing) { "0" } + right
  if (expanded.any { !Regex("[0-9a-fA-F]{1,4}").matches(it) }) throw IOException("Invalid IPv6 group")
  val bytes = ByteArray(16)
  expanded.forEachIndexed { index, group ->
    val number = group.toInt(16)
    bytes[index * 2] = (number ushr 8).toByte()
    bytes[index * 2 + 1] = number.toByte()
  }
  return InetAddress.getByAddress(bytes)
}

internal fun publicAddress(address: InetAddress): Boolean {
  val b = address.address.map { it.toInt() and 255 }
  if (b.size == 4) {
    return !(b[0] == 0 || b[0] == 10 || b[0] == 127 || b[0] >= 224 ||
      (b[0] == 100 && b[1] in 64..127) || (b[0] == 169 && b[1] == 254) ||
      (b[0] == 172 && b[1] in 16..31) ||
      (b[0] == 192 && (b[1] == 168 || (b[1] == 0 && (b[2] == 0 || b[2] == 2)) || (b[1] == 88 && b[2] == 99))) ||
      (b[0] == 198 && (b[1] in 18..19 || (b[1] == 51 && b[2] == 100))) ||
      (b[0] == 203 && b[1] == 0 && b[2] == 113))
  }
  return b.size == 16 && b[0] in 0x20..0x3f &&
    !(b[0] == 0x20 && b[1] == 0x01 && (b[2] < 2 || (b[2] == 0x0d && b[3] == 0xb8))) &&
    !(b[0] == 0x20 && b[1] == 0x02) &&
    !(b[0] == 0x3f && b[1] == 0xff)
}
